// --- InnoVeg Production State Machine Engine ---
const body = $json.body || {};
const entry = body.entry?.[0]?.changes?.[0]?.value || body;
const message = entry.messages?.[0] || body.message || body.data?.message || {};

// Clean sender phone number
let rawPhone = message.from || body.from || body.phone || body.lead?.phone_number || "Unknown";
const phone = rawPhone.toString().replace(/[^0-9]/g, '');

// Detect message type and content
const msgType = message.type || (message.text ? 'text' : message.location ? 'location' : message.image ? 'image' : 'unknown');
const text = (message.text?.body || message.caption || body.text || '').trim();
const hasLocation = msgType === 'location' || !!message.location;
const lat = message.location?.latitude || body.latitude;
const lng = message.location?.longitude || body.longitude;
const hasImage = msgType === 'image' || !!message.image;
const photoId = message.image?.id || body.media_url || body.photoUrl || null;

// Retrieve session from Postgres or fallback memory
let dbSession = $input.first()?.json || {};
let currentStep = dbSession.currentStep || "START";
let tempData = dbSession.tempVisitData ? (typeof dbSession.tempVisitData === 'string' ? JSON.parse(dbSession.tempVisitData) : dbSession.tempVisitData) : {};

// Reset command check
const textLower = text.toLowerCase();
if (['hi', 'hello', 'hey', 'start', 'reset', 'restart', '0', 'cancel'].includes(textLower)) {
  currentStep = "START";
  tempData = {};
}

let replyText = "";
let nextStep = currentStep;
let requiresAI = false;
let isFinished = false;

switch (currentStep) {
  case "START":
    replyText = "🌾 *Welcome to InnoVeg Field Reporting System!*\n\nPlease reply with the visit type:\n1️⃣ *Farmer*\n2️⃣ *Dealer*\n\n_(Reply 1/Farmer or 2/Dealer)_";
    nextStep = "AWAITING_VISIT_TYPE";
    break;

  case "AWAITING_VISIT_TYPE":
    if (textLower.includes('farmer') || textLower === '1') {
      tempData.visitType = "Farmer";
      replyText = "👍 *Visit Type*: Farmer\n\nNext, please enter the **Farmer Name** (e.g., Ramesh Kumar):";
      nextStep = "AWAITING_ENTITY_NAME";
    } else if (textLower.includes('dealer') || textLower === '2') {
      tempData.visitType = "Dealer";
      replyText = "👍 *Visit Type*: Dealer\n\nNext, please enter the **Dealer / Shop Name** (e.g., Gupta Krishi Kendra):";
      nextStep = "AWAITING_ENTITY_NAME";
    } else {
      replyText = "⚠️ Please select a valid option:\n1️⃣ *Farmer*\n2️⃣ *Dealer*";
    }
    break;

  case "AWAITING_ENTITY_NAME":
    if (text.length >= 2) {
      tempData.entityName = text;
      replyText = `👤 **Name Recorded**: ${text}\n\nNext, please enter the **Village / Town Name** (e.g., Rampur, Sehore):`;
      nextStep = "AWAITING_VILLAGE";
    } else {
      replyText = "⚠️ Please enter a valid name (at least 2 characters).";
    }
    break;

  case "AWAITING_VILLAGE":
    if (text.length >= 2) {
      tempData.village = text;
      replyText = `📍 **Village/Town**: ${text}\n\nNow, please send your **Live GPS Location** using WhatsApp location sharing 📌`;
      nextStep = "AWAITING_LOCATION";
    } else {
      replyText = "⚠️ Please enter a valid village or town name.";
    }
    break;

  case "AWAITING_LOCATION":
    if (hasLocation && lat && lng) {
      tempData.latitude = parseFloat(lat);
      tempData.longitude = parseFloat(lng);
      replyText = `📍 **Location Captured**: (${lat}, ${lng})\n\nNow, please send a **Photo** of the visit 📷`;
      nextStep = "AWAITING_PHOTO";
    } else {
      replyText = "⚠️ Location not detected. Please use WhatsApp 📎 -> **Location** to send your GPS coordinates.";
    }
    break;

  case "AWAITING_PHOTO":
    if (hasImage || photoId || textLower.includes('skip')) {
      tempData.photoId = photoId || 'sample_photo';
      tempData.photoUrl = photoId ? `https://graph.facebook.com/v20.0/${photoId}` : 'https://images.unsplash.com/photo-1592417817098-8f3d6eb22513?w=600&auto=format&fit=crop&q=80';
      requiresAI = true;
      replyText = "📷 **Photo Received!**\n\nLastly, please enter any **Remarks / Observations** for this visit (or type *None*):";
      nextStep = "AWAITING_REMARKS";
    } else {
      replyText = "⚠️ Please attach a photo of the visit using the camera / gallery icon 📷.";
    }
    break;

  case "AWAITING_REMARKS":
    tempData.remarks = text || "No specific remarks";
    isFinished = true;
    nextStep = "START";
    replyText = `✅ *FIELD VISIT REPORT SUBMITTED SUCCESSFULLY!*\n\n📋 **Summary**:\n• **Type**: ${tempData.visitType}\n• **Name**: ${tempData.entityName}\n• **Village**: ${tempData.village}\n• **GPS**: ${tempData.latitude}, ${tempData.longitude}\n• **Remarks**: ${tempData.remarks}\n\nYour report is now live on the InnoVeg Dashboard! 🚀\n\n_(Type Hi anytime to record a new visit)_`;
    break;

  default:
    currentStep = "START";
    replyText = "🌾 *Welcome to InnoVeg Field Reporting System!*\n\nPlease reply with the visit type:\n1️⃣ *Farmer*\n2️⃣ *Dealer*";
    nextStep = "AWAITING_VISIT_TYPE";
    break;
}

return [{
  json: {
    phone,
    replyText,
    currentStep: nextStep,
    requiresAI,
    isFinished,
    tempData,
    nextjsPayload: {
      employeeMobile: phone,
      visitType: tempData.visitType || 'Farmer',
      entityName: tempData.entityName || 'Field Visit',
      village: tempData.village || 'Field',
      latitude: tempData.latitude || 23.2599,
      longitude: tempData.longitude || 77.4126,
      photoUrl: tempData.photoUrl || 'https://images.unsplash.com/photo-1592417817098-8f3d6eb22513?w=600&auto=format&fit=crop&q=80',
      remarksBooking: tempData.remarks || 'Recorded via WhatsApp Bot',
      aiAnalysis: {
        qualityScore: 90,
        isBlur: false,
        fieldVisible: true,
        personVisible: true,
        brandingVisible: true,
        visitTypeMatch: true,
        summaryHindi: `${tempData.visitType || 'Farmer'} visit completed at ${tempData.village || 'Field'}. Remarks: ${tempData.remarks || 'Good'}`,
        summaryEnglish: `${tempData.visitType || 'Farmer'} visit logged for ${tempData.entityName || 'Entity'}.`,
        tags: [tempData.visitType || 'Farmer', 'n8n-bot', 'verified-gps']
      }
    }
  }
}];
